-- Программа «Герой и Бунтарь. Создание бренда с помощью архетипов»
-- Slug: heroes-and-outlaws
-- Книга: Маргарет Марк, Кэрол Пирсон. McGraw-Hill 2001 / Питер 2005.
-- Тип: маркетинг/брендинг + психология архетипов (Юнг, Пирсон)
-- Features: free_chat, author_chat, portrait, modes (test и themes — отдельные seed'ы)
-- Архетипы режимов: Лекция ×1 + Анализ ×3 + Воркшоп ×1 + Ролевая ×1 + Экзамен ×1
-- Тон Система: «архетипический стратег» — спокойный, аналитический, на «ты»
-- =============================================================================

INSERT INTO programs (
  slug,
  title,
  description,
  system_prompt,
  anonymous_system_prompt,
  free_chat_welcome,
  author_chat_system_prompt,
  author_chat_welcome,
